/* Learning milestones derive from the existing question bank and local progress. */
const MILESTONE_GUIDES={
 bedrock:{title:'Choose the right approach',outcome:'Jelaskan kapan memakai prompt, RAG, atau fine-tuning, lalu hitung similarity sederhana.',scenario:'Tim support perlu menjawab kebijakan yang berubah setiap minggu. Pilih sumber konteks dan pendekatan model yang masuk akal.',bridge:'Sesudah memilih RAG, pelajari cara menemukan konteks yang tepat.'},
 retrieval:{title:'Find trustworthy context',outcome:'Bedakan masalah chunking, izin akses, freshness, dan kualitas jawaban.',scenario:'Jawaban terdengar meyakinkan tetapi mengambil kebijakan lama atau dokumen tenant lain. Telusuri sumber kegagalannya.',bridge:'Konteks yang tepat masih perlu diubah menjadi output yang dapat diperiksa.'},
 delivery:{title:'Build a reliable response',outcome:'Susun prompt, periksa JSON, dan bedakan guardrails dari aturan bisnis.',scenario:'Aplikasi harus menghasilkan JSON valid dan mematuhi kebijakan. Tentukan pemeriksaan sebelum respons dipakai aplikasi.',bridge:'Gabungkan alur respons dengan keamanan dan lifecycle perusahaan.'},
 enterprise:{title:'Connect the whole system',outcome:'Jelaskan trust boundaries dan keputusan integrasi dari ingestion hingga evaluasi.',scenario:'Asisten perusahaan menerima instruksi berbahaya di dalam dokumen. Jelaskan apa yang harus dipercaya dan apa yang perlu dibatasi.',bridge:'Ulangi recall pada hari berbeda. Bab lanjutan PDF masih menunggu pengembangan.'}
};
function milestoneProgress(m){
 const qs=QUESTIONS.filter(q=>m.lessons.includes(q.lesson)),latest=m.lessons.flatMap(latestAttempts);
 const labIds=Object.entries(LABS).filter(([,l])=>m.lessons.includes(l.lesson)).map(([id])=>id);
 const read=m.lessons.filter(id=>state.read[id]).length,correct=latest.filter(a=>a.correct).length,labs=labIds.filter(id=>state.labs[id]).length;
 const review=m.lessons.filter(id=>status(id)==='review'),done=read===m.lessons.length&&correct===qs.length&&labs===labIds.length&&!review.length;
 const checks=read+correct+labs,total=m.lessons.length+qs.length+labIds.length;
 const minutes=m.lessons.reduce((s,id)=>s+byId(id).minutes+15,0)+labIds.length*12;
 let next;
 if(review.length)next={path:'lesson/'+review[0],label:'Review '+byId(review[0]).title,kind:'review'};
 else if(read<m.lessons.length){const id=m.lessons.find(id=>!state.read[id]);next={path:'lesson/'+id,label:'Baca '+byId(id).title,kind:'read'};}
 else if(correct<qs.length)next={module:m.id,label:'Uji keputusan · '+(qs.length-correct)+' soal belum benar',kind:'practice'};
 else if(labs<labIds.length){const id=labIds.find(id=>!state.labs[id]);next={path:'labs/'+id,label:'Coba '+LABS[id].name,kind:'lab'};}
 else next={path:'revision',label:'Siapkan spaced review',kind:'review'};
 return {read,correct,labs,labIds,review,done,checks,total,minutes,next,questions:qs.length,started:checks>0||review.length>0};
}
function milestoneButton(next,label,classes='primary'){
 return `<button class="${classes}" ${next.module?`data-milestone-practice="${next.module}"`:`data-go="${next.path}"`}>${esc(label||next.label)} →</button>`;
}
function milestoneStatus(p){return p.review.length?'Perlu review':p.done?'Milestone tercapai':p.started?'Sedang dipelajari':'Siap dimulai';}
function milestoneRows(){return MODULES.map((m,i)=>{const p=milestoneProgress(m),g=MILESTONE_GUIDES[m.id];return `<article class="journey-row ${p.done?'is-done':''}"><div class="journey-marker" aria-label="Milestone ${i+1}">${p.done?icon('practice'):i+1}</div><div class="journey-content"><div class="row space-between"><h3><a href="#milestones/${m.id}">${esc(g.title)}</a></h3><span class="badge ${p.review.length?'review':p.done?'strong':''}">${milestoneStatus(p)}</span></div><p>${esc(g.outcome)}</p><div class="journey-evidence"><span>${p.read}/${m.lessons.length} dibaca</span><span>${p.correct}/${p.questions} soal benar</span>${p.labIds.length?`<span>${p.labs}/${p.labIds.length} lab checks</span>`:'<span>Challenge skenario integrasi</span>'}</div><div class="progress-bar" role="progressbar" aria-label="Checklist milestone ${i+1}" aria-valuenow="${p.checks}" aria-valuemin="0" aria-valuemax="${p.total}"><span style="width:${p.checks/p.total*100}%"></span></div><a class="journey-link" href="#milestones/${m.id}">${p.done?'Lihat bukti & ulangi':'Lihat langkah milestone'} →</a></div></article>`;}).join('');}
function renderMilestones(){
 const selected=location.hash.split('/')[1],m=MODULES.find(m=>m.id===selected)||MODULES.find(m=>!milestoneProgress(m).done)||MODULES[0],p=milestoneProgress(m),g=MILESTONE_GUIDES[m.id];
 const done=MODULES.filter(m=>milestoneProgress(m).done).length,days=Math.ceil(MODULES.reduce((s,m)=>s+milestoneProgress(m).minutes,0)/state.preferences.minutes);
 $('#main').innerHTML=head('Small steps. Clear milestones.','Empat milestone menghubungkan model → konteks → respons → sistem. Semua materi boleh dijelajahi; status mengikuti bukti belajar Anda.')+
 `<div class="milestone-summary"><strong>${done} dari ${MODULES.length} milestone tercapai</strong><span>Fondasi tersedia · sekitar ${days} hari pada ${state.preferences.minutes} menit/hari</span></div><div class="milestone-layout"><section aria-label="Peta milestone"><h2 class="sr-only">Milestone path</h2>${milestoneRows()}</section><section class="milestone-detail" id="milestone-detail" tabindex="-1" aria-label="Detail milestone"><a class="back-link" href="#milestones">← Peta milestone</a><div class="row space-between"><span class="badge ${p.review.length?'review':p.done?'strong':''}">${milestoneStatus(p)}</span><span class="small-text muted">Milestone ${MODULES.indexOf(m)+1} / ${MODULES.length}</span></div><h2>${esc(g.title)}</h2><p>${esc(g.scenario)}</p><h3>Langkah Anda</h3><ol class="task-list">${m.lessons.map(id=>{const l=byId(id),correct=latestAttempts(id).filter(a=>a.correct).length;return `<li><div><a href="#lesson/${id}">${esc(l.title)}</a><span class="small-text muted">${l.minutes} menit baca · ${state.read[id]?'ditandai dibaca':'belum dibaca'} · ${correct}/3 soal benar</span></div>${badge(id)}</li>`;}).join('')}</ol>${p.labIds.length?`<h3>Terapkan di lab</h3><div class="lab-checks">${p.labIds.map(id=>`<a href="#labs/${id}">${icon('labs')}<span>${esc(LABS[id].name)}</span><span class="small-text">${state.labs[id]?'Check tercapai':'Coba lab →'}</span></a>`).join('')}</div>`:'<p class="small-text muted">Milestone ini diperiksa melalui skenario pada practice kedua lesson.</p>'}
 <div class="milestone-next"><strong>Langkah berikutnya</strong><p>${p.done?'Checklist selesai. Beri jarak sebelum recall berikutnya.':esc(p.next.label)}</p>${p.done?'<button class="primary" data-action="next-milestone">Lanjut ke milestone berikutnya →</button>':milestoneButton(p.next,'Mulai langkah ini')}</div><details class="detail"><summary>Apa arti “tercapai”?</summary><p>Semua lesson ditandai dibaca (self-assessment), seluruh soal memiliki jawaban terbaru yang benar, lab checks terkait tercapai, dan tidak ada tanda bingung atau jawaban terbaru yang salah. Status dapat kembali ke “Perlu review”.</p><p>Ini checklist belajar, bukan jaminan mastery atau kesiapan ujian. Bukti penguasaan lebih kuat tetap membutuhkan jawaban benar berulang dengan jarak ≥24 jam.</p></details><p class="small-text muted">${esc(g.bridge)}</p></section></div>`;
}
function guideMarkup(id){
 const l=byId(id),steps=[['intuition','Pahami masalah'],['flow','Ikuti alur'],['example','Lihat contoh'],['recall','Coba jelaskan']];
 const content={intuition:`<h3>Masalah apa yang diselesaikan?</h3><p>${esc(l.intro)}</p>`,flow:`<h3>Hubungkan langkahnya</h3><ol class="guide-flow">${l.diagram.map((x,i)=>`<li><span>${i+1}</span>${esc(x)}</li>`).join('')}</ol><p class="cue">${esc(l.cue)}</p><a href="#mechanism" data-anchor="mechanism">Baca mekanisme lengkap ↓</a>`,example:`<h3>${esc(l.example.title)}</h3><p>${esc(l.example.body)}</p>`,recall:`<h3>Jelaskan dengan kata Anda</h3><p>${esc(l.recall[0][0])}</p><p class="small-text muted">Ucapkan atau tulis jawaban sebelum membuka pembanding.</p><details class="detail"><summary>Reveal contoh jawaban</summary><p>${esc(l.recall[0][1])}</p></details><a href="#recall" data-anchor="recall">Tulis recall & simpan jawaban ↓</a>`};
 return `<div class="guide-heading"><h2>Pahami dulu, baru hafalkan.</h2><p class="small-text muted">Panduan singkat. Penjelasan lengkap tetap tersedia di bawah.</p></div><div class="guide-controls" role="group" aria-label="Langkah panduan lesson">${steps.map(([key,label],i)=>`<button data-guide-step="${key}" data-guide-lesson="${id}" aria-pressed="${guideStep===key}"><span>${i+1}</span>${label}</button>`).join('')}</div><div class="guide-content" aria-live="polite">${content[guideStep]||content.intuition}</div>`;
}
function renderDashboard(){
 const estimatedMinutes=MODULES.reduce((s,m)=>s+milestoneProgress(m).minutes,0),planDays=Math.ceil(estimatedMinutes/state.preferences.minutes);
 const current=MODULES.find(m=>!milestoneProgress(m).done),m=current||MODULES[MODULES.length-1],p=milestoneProgress(m),g=MILESTONE_GUIDES[m.id];
 const done=MODULES.filter(m=>milestoneProgress(m).done).length,due=dueLessons(),read=LESSONS.filter(l=>state.read[l.id]).length,strong=LESSONS.filter(l=>status(l.id)==='strong').length;
 $('#main').innerHTML=head('Build understanding, one quest at a time.','Pahami konsep, uji alasan, lalu coba mekanismenya. Foundation edition: PDF p. 17–74 dari 682 halaman.')+
 `<section class="mission" aria-label="Misi belajar berikutnya"><div class="mission-main"><h2>${current?esc(g.title):'Your foundation path is complete.'}</h2><p>${current?esc(g.scenario):'Empat milestone tercapai. Kembali pada hari berbeda untuk memperkuat recall dan periksa konsep yang masih membingungkan.'}</p><ol class="session-steps"><li><strong>Pahami</strong><span>Baca intuisi & contoh.</span></li><li><strong>Uji alasan</strong><span>Jawab sebelum reveal.</span></li><li><strong>Terapkan</strong><span>Coba lab & periksa hasil.</span></li></ol></div><div class="mission-next"><span class="mission-position">${current?'Milestone '+(MODULES.indexOf(m)+1)+' dari 4':'Langkah berikutnya'}</span><h3>${current?esc(p.next.label):'Spaced review'}</h3><p>${p.next.kind==='read'?'Mulai dengan satu lesson. Buka panduan singkat, lalu lanjut ke penjelasan lengkap.':p.next.kind==='practice'?'Tunjukkan pemahaman melalui jawaban aktual. Feedback menjelaskan setiap opsi.':p.next.kind==='lab'?'Ubah parameter, amati hasil, dan jelaskan mengapa hasilnya berubah.':'Telusuri kesalahan sebelum melanjutkan. Progres mengikuti jawaban terbaru.'}</p>${milestoneButton(current?p.next:{path:'revision'},current?'Continue learning':'Buka review','gold')}<a href="#milestones/${m.id}">Lihat checklist milestone →</a></div></section>
 <div class="learning-summary"><span><strong>${done}/4</strong> milestone tercapai</span><span>${read}/14 dibaca · self-assessment</span><span>${strong}/14 bukti lebih kuat</span><a href="#settings">Export / import progres →</a></div>
 <div class="dashboard-grid"><section><div class="section-top"><h2>Your learning journey</h2><a href="#milestones">Semua milestones →</a></div>${milestoneRows()}<details class="detail"><summary>Bagaimana milestone dan XP dihitung?</summary><p>Milestone memerlukan status baca, seluruh jawaban terbaru benar, dan lab checks terkait. Membaca adalah self-assessment. Practice dan lab checks memberi bukti tambahan; semuanya masih bukan prediksi nilai ujian.</p><div class="badges">${awards()}</div><p class="small-text muted">10 XP per soal unik yang pertama kali benar; 15 XP per lab check pertama. Retry tidak menggandakan XP.</p></details></section>
 <aside class="dashboard-aside"><section class="study-session"><h2>A manageable study session</h2><p>Satu lesson dahulu. Tak perlu menuntaskan satu milestone sekaligus.</p><ul><li>Baca satu konsep dan worked example.</li><li>Jelaskan kembali dengan kata Anda.</li><li>Jawab 3 soal, lalu telusuri feedback.</li></ul><p class="small-text muted">Rencana sementara: ${state.preferences.minutes} menit/hari, sekitar ${planDays} hari untuk fondasi yang tersedia. Pemula mungkin memerlukan waktu tambahan.</p><a href="#settings">Sesuaikan waktu belajar →</a></section>
 <section class="review-preview"><h2>Review queue <span>${due.length}</span></h2>${due.length?`<p>${due.slice(0,2).map(l=>lessonLink(l.id)).join('<br>')}</p><button class="primary small" data-action="start-review">Latih review queue</button>`:'<p>Belum ada review jatuh tempo. Jawaban salah dan tanda “masih bingung” akan masuk di sini.</p>'}</section>
 ${!state.diagnostic?'<section class="diagnostic-preview"><h2>Find your starting point</h2><p>Empat soal opsional membantu melihat konsep yang perlu didahulukan.</p><div class="row"><button class="small" data-go="diagnostic">Mulai diagnostic</button><button class="small quiet" data-action="skip-diagnostic">Lewati</button></div></section>':''}
 <section class="coverage-preview"><h2>Foundation edition</h2><p>14 lessons · 42 soal orisinal · 7 labs.</p><p>PDF p. 17–74 sudah diajarkan. P. 75–682 belum tersedia sebagai lesson.</p><a href="#coverage">Lihat sumber & cakupan →</a></section></aside></div>`;
}
